import { NextResponse } from 'next/server';
import { generateWithRetry } from '@/lib/gemini';
import { cleanAndParseJSON } from '@/lib/gemini-json';

// Free-tier Gemini API outputs ~11KB per call (~20-25 rows of typical data).
// We split large requests into batches of this size and merge the results.
const BATCH_SIZE = 20;

export async function POST(req: Request) {
  if (!process.env.GEMINI_API_KEY) {
    return NextResponse.json(
      { error: 'Server configuration error: GEMINI_API_KEY is not set in .env.local' },
      { status: 500 }
    );
  }

  try {
    const { schema, rowCount, locale, injectEdgeCases } = await req.json();

    if (!schema || schema.trim() === '') {
      return NextResponse.json({ error: 'Schema definition is required' }, { status: 400 });
    }

    const totalRows = Math.min(Math.max(1, rowCount || 10), 100);
    const edgeNote = injectEdgeCases
      ? 'YES — include 5-10% edge cases: null fields, outlier values, unusual formats.'
      : 'NO — keep data clean and realistic.';

    // Build a concise prompt builder for a given batch size
    const buildPrompt = (batchRows: number, batchIndex: number) => `
You are a synthetic data generator. Output ONLY a valid JSON array — no markdown, no explanation.

Schema: ${schema}
Locale: ${locale || 'en-US'}
Edge cases: ${edgeNote}
Rows to generate: ${batchRows}
Start IDs from: ${batchIndex * BATCH_SIZE + 1}

Output a JSON array of ${batchRows} objects matching the schema. Start with [ and end with ].
`.trim();

    // Split into batches
    const numBatches = Math.ceil(totalRows / BATCH_SIZE);
    let allRows: any[] = [];

    for (let b = 0; b < numBatches; b++) {
      const batchRows = Math.min(BATCH_SIZE, totalRows - b * BATCH_SIZE);
      const prompt = buildPrompt(batchRows, b);

      const raw = await generateWithRetry(prompt);
      const batch = cleanAndParseJSON<any[]>(raw);

      if (!Array.isArray(batch)) {
        throw new Error(`Batch ${b + 1} returned unexpected format (not an array).`);
      }
      allRows = allRows.concat(batch);
    }

    return NextResponse.json({ data: allRows });

  } catch (error: any) {
    const message =
      error?.errorDetails?.[0]?.message ||
      error?.message ||
      'Internal Server Error';
    console.error('[/api/generate/tabular] Error:', message);
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
